extends Node

const SAVE_SCHEMA_VERSION := 3
const MIN_SUPPORTED_ENVELOPE_SCHEMA := 2
const SAVE_PATH := "user://hayat_tounes_save.json"
const TEMP_PATH := "user://hayat_tounes_save.tmp"
const BACKUP_PATH := "user://hayat_tounes_save.backup.json"
const MAX_SAVE_BYTES := 4 * 1024 * 1024

var last_load_source: String = "none"
var last_error: String = ""
var last_migration_source: String = "none"

func save_game(extra := {}) -> bool:
    last_error = ""
    last_migration_source = "none"
    var payload := _build_payload(extra)
    var payload_json := JSON.stringify(payload)
    var envelope := {
        "schema_version": SAVE_SCHEMA_VERSION,
        "build_version": _current_build_version(),
        "saved_at_utc": Time.get_datetime_string_from_system(true),
        "payload_sha256": _payload_hash(payload),
        "payload": payload
    }
    var encoded := JSON.stringify(envelope)
    if encoded.to_utf8_buffer().size() > MAX_SAVE_BYTES:
        last_error = "save_too_large"
        return false

    if not _write_text(TEMP_PATH, encoded):
        last_error = "temp_write_failed"
        return false

    var temp_global := ProjectSettings.globalize_path(TEMP_PATH)
    var save_global := ProjectSettings.globalize_path(SAVE_PATH)
    var backup_global := ProjectSettings.globalize_path(BACKUP_PATH)

    if FileAccess.file_exists(SAVE_PATH):
        if FileAccess.file_exists(BACKUP_PATH):
            DirAccess.remove_absolute(backup_global)
        var backup_result := DirAccess.copy_absolute(save_global, backup_global)
        if backup_result != OK:
            DirAccess.remove_absolute(temp_global)
            last_error = "backup_failed:%s" % backup_result
            return false

    if FileAccess.file_exists(SAVE_PATH):
        var remove_result := DirAccess.remove_absolute(save_global)
        if remove_result != OK:
            DirAccess.remove_absolute(temp_global)
            last_error = "replace_remove_failed:%s" % remove_result
            return false

    var rename_result := DirAccess.rename_absolute(temp_global, save_global)
    if rename_result != OK:
        last_error = "replace_rename_failed:%s" % rename_result
        if FileAccess.file_exists(BACKUP_PATH) and not FileAccess.file_exists(SAVE_PATH):
            DirAccess.copy_absolute(backup_global, save_global)
        return false

    return true

func load_game() -> Dictionary:
    last_error = ""
    last_load_source = "none"
    last_migration_source = "none"

    var primary := _read_and_validate(SAVE_PATH)
    if primary.get("valid", false):
        last_load_source = "primary"
        return _apply_payload(_migrate_payload(primary))

    var backup := _read_and_validate(BACKUP_PATH)
    if backup.get("valid", false):
        last_load_source = "backup"
        last_error = "primary_invalid_recovered_from_backup"
        return _apply_payload(_migrate_payload(backup))

    if FileAccess.file_exists(SAVE_PATH) or FileAccess.file_exists(BACKUP_PATH):
        last_error = "no_valid_save"
    return {}

func _build_payload(extra: Dictionary) -> Dictionary:
    return {
        "version": SAVE_SCHEMA_VERSION,
        "build_version": _current_build_version(),
        "money": GameState.money,
        "water": GameState.water,
        "fuel": GameState.fuel,
        "energy": GameState.energy,
        "mood": GameState.mood,
        "current_vehicle_id": GameState.current_vehicle_id,
        "current_district": GameState.current_district,
        "fuel_shortage": GameState.fuel_shortage,
        "water_shortage": GameState.water_shortage,
        "missions": GameState.missions.duplicate(true),
        "world_state": extra.get("world_state", {}),
        "extra": extra
    }

func _read_and_validate(path: String) -> Dictionary:
    if not FileAccess.file_exists(path):
        return {"valid": false, "reason": "missing"}
    var file := FileAccess.open(path, FileAccess.READ)
    if file == null:
        return {"valid": false, "reason": "open_failed"}
    var length := file.get_length()
    if length < 0 or length > MAX_SAVE_BYTES:
        return {"valid": false, "reason": "file_too_large"}
    var json := JSON.new()
    if json.parse(file.get_as_text()) != OK:
        return {"valid": false, "reason": "invalid_json"}
    var parsed = json.data
    if typeof(parsed) != TYPE_DICTIONARY:
        return {"valid": false, "reason": "invalid_json"}

    # v1 compatibility: the old save format stored state directly at the root.
    if parsed.has("money") and not parsed.has("payload"):
        return {"valid": true, "payload": parsed, "legacy": true, "schema_version": 1}

    var schema := int(parsed.get("schema_version", 0))
    if schema < MIN_SUPPORTED_ENVELOPE_SCHEMA or schema > SAVE_SCHEMA_VERSION:
        return {"valid": false, "reason": "unsupported_schema"}
    var payload = parsed.get("payload", {})
    if typeof(payload) != TYPE_DICTIONARY:
        return {"valid": false, "reason": "payload_not_dictionary"}
    var expected := str(parse

d.get("payload_sha256", ""))
    if expected.is_empty():
        return {"valid": false, "reason": "checksum_missing"}
    var canonical_actual := _payload_hash(payload)
    var legacy_actual := _sha256(JSON.stringify(payload))
    if expected.to_lower() != canonical_actual.to_lower() and expected.to_lower() != legacy_actual.to_lower():
        return {"valid": false, "reason": "checksum_mismatch"}
    return {
        "valid": true,
        "payload": payload,
        "legacy": schema < SAVE_SCHEMA_VERSION,
        "schema_version": schema,
        "build_version": str(parsed.get("build_version", "unknown"))
    }

func _migrate_payload(read_result: Dictionary) -> Dictionary:
    var payload = read_result.get("payload", {})
    if typeof(payload) != TYPE_DICTIONARY:
        return {}
    payload = payload.duplicate(true)
    var schema := int(read_result.get("schema_version", 1))
    if schema < 2:
        last_migration_source = "v1_to_v3"
    elif schema == 2:
        last_migration_source = "v2_to_v3"
    else:
        last_migration_source = "none"

    # v3 introduces explicit build metadata while preserving the v2 payload shape.
    payload["version"] = SAVE_SCHEMA_VERSION
    if str(payload.get("build_version", "")).is_empty():
        payload["build_version"] = str(read_result.get("build_version", "legacy"))
    return payload

func _apply_payload(parsed: Dictionary) -> Dictionary:
    GameState.money = _finite_non_negative(parsed.get("money", 12.0), 12.0)
    GameState.water = _finite_percent(parsed.get("water", 48.0), 48.0)
    GameState.fuel = _finite_percent(parsed.get("fuel", 42.0), 42.0)
    GameState.energy = _finite_percent(parsed.get("energy", 95.0), 95.0)
    GameState.mood = _finite_percent(parsed.get("mood", 72.0), 72.0)
    GameState.current_vehicle_id = str(parsed.get("current_vehicle_id", ""))
    GameState.current_district = str(parsed.get("current_district", "tunis_centre"))
    if GameState.current_district.is_empty():
        GameState.current_district = "tunis_centre"
    GameState.fuel_shortage = bool(parsed.get("fuel_shortage", false))
    GameState.water_shortage = bool(parsed.get("water_shortage", false))

    var missions_value = parsed.get("missions", {})
    if typeof(missions_value) == TYPE_DICTIONARY:
        for mission_id in GameState.missions.keys():
            if missions_value.has(mission_id):
                var restored_state := str(missions_value[mission_id])
                if restored_state in ["locked", "active", "completed"]:
                    GameState.missions[mission_id] = restored_state

    var extra = parsed.get("extra", {})
    if typeof(extra) != TYPE_DICTIONARY:
        extra = {}
    if not extra.has("world_state"):
        var world_state = parsed.get("world_state", {})
        if typeof(world_state) == TYPE_DICTIONARY:
            extra["world_state"] = world_state
    return extra

func _finite_percent(value, fallback: float) -> float:
    var number := float(value)
    if is_nan(number) or is_inf(number):
        number = fallback
    return clampf(number, 0.0, 100.0)

func _finite_non_negative(value, fallback: float) -> float:
    var number := float(value)
    if is_nan(number) or is_inf(number):
        number = fallback
    return maxf(0.0, number)

func _current_build_version() -> String:
    return str(ProjectSettings.get_setting("application/config/version", "unknown"))

func _write_text(path: String, text: String) -> bool:
    var file := FileAccess.open(path, FileAccess.WRITE)
    if file == null:
        return false
    file.store_string(text)
    file.flush()
    return file.get_error() == OK


func _payload_hash(payload: Dictionary) -> String:
    return _sha256(JSON.stringify(_canonicalize_variant(payload)))

func _canonicalize_variant(value):
    if typeof(value) == TYPE_INT or typeof(value) == TYPE_FLOAT:
        # Godot JSON decodes all JSON numbers as float. Normalizing numeric variants
        # before hashing keeps the digest stable across serialize/parse round-trips.
        return float(value)
    if typeof(value) == TYPE_DICTIONARY:
        var source: Dictionary = value
        var keys: Array = source.keys()
        keys.sort_custom(func(a, b): return str(a) < str(b))
        var ordered := {}
        for key in keys:
            ordered[key] = _canonicalize_variant(source[key])
        return ordered
    if typeof(value) == TYPE_ARRAY:
        var result: Array = []
        for item in value:
            result.append(_canonicalize_variant(item))
        return result
    return value

func _sha256(text: String) -> String:
    var context := HashingContext.new()
    var start_error := context.start(HashingContext.HASH_SHA256)
    if start_error != OK:
        return ""
    context.update(text.to_utf8_buffer())
    return context.finish().hex_encode()
